#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:3c1a9e70-6f2b-4d8e-a1c3-5b7d9f0e2a11\",\n  \"type\": \"https://trusttasks.org/spec/webvh/sync/update/0.2\",\n  \"issuer\": \"did:webvh:QmControlScid2:control.example.com\",\n  \"recipient\": \"did:webvh:QmNodeScid3:node1.example.com\",\n  \"issuedAt\": \"2026-09-27T09:00:00Z\",\n  \"payload\": {\n    \"mnemonic\": \"alice\",\n    \"didId\": \"did:webvh:QmAliceScid4:did.example.com:alice\",\n    \"logContent\": \"{\\\"versionId\\\":\\\"1-QmA\\\",\\\"versionTime\\\":\\\"2026-09-01T10:00:00Z\\\"}\\n{\\\"versionId\\\":\\\"2-QmB\\\",\\\"versionTime\\\":\\\"2026-09-27T08:59:00Z\\\"}\",\n    \"witnessContent\": \"[{\\\"versionId\\\":\\\"2-QmB\\\",\\\"proof\\\":[]}]\",\n    \"versionCount\": 2,\n    \"disabled\": false\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:3c1a9e70-6f2b-4d8e-a1c3-5b7d9f0e2a12\",\n  \"type\": \"https://trusttasks.org/spec/webvh/sync/update/0.2#response\",\n  \"threadId\": \"urn:uuid:3c1a9e70-6f2b-4d8e-a1c3-5b7d9f0e2a11\",\n  \"issuer\": \"did:webvh:QmNodeScid3:node1.example.com\",\n  \"recipient\": \"did:webvh:QmControlScid2:control.example.com\",\n  \"issuedAt\": \"2026-09-27T09:00:01Z\",\n  \"payload\": { \"mnemonic\": \"alice\", \"status\": \"applied\" }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Missing disabled — a replica must never guess whether to serve the slot.",
                "{\n  \"didId\": \"did:webvh:QmA:did.example.com:alice\",\n  \"logContent\": \"{}\",\n  \"mnemonic\": \"alice\",\n  \"versionCount\": 1\n}",
            ),
            (
                "snake_case members from 0.1's wire drift are not accepted.",
                "{\n  \"did_id\": \"did:webvh:QmA:did.example.com:alice\",\n  \"disabled\": false,\n  \"log_content\": \"{}\",\n  \"mnemonic\": \"alice\",\n  \"version_count\": 1\n}",
            ),
            (
                "Empty logContent.",
                "{\n  \"didId\": \"did:webvh:QmA:did.example.com:alice\",\n  \"disabled\": false,\n  \"logContent\": \"\",\n  \"mnemonic\": \"alice\",\n  \"versionCount\": 1\n}",
            ),
            (
                "versionCount below 1.",
                "{\n  \"didId\": \"did:webvh:QmA:did.example.com:alice\",\n  \"disabled\": false,\n  \"logContent\": \"{}\",\n  \"mnemonic\": \"alice\",\n  \"versionCount\": 0\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
